import {assert,identity,frame,body} from './core.mjs';
export class MidiTransport{
  constructor(input,output,onDisconnect){this.input=input;this.output=output;this.closed=false;this.pending=null;this.receive=e=>{const m=Uint8Array.from(e.data);if(this.pending&&this.pending.match(m))this.pending.resolve(m);};input.addEventListener('midimessage',this.receive);this.onDisconnect=onDisconnect;}
  request(data,match,timeout=3000){assert(!this.closed&&this.input.state==='connected'&&this.output.state==='connected','Conexão USB indisponível.');assert(!this.pending,'Uma operação MIDI já está em andamento.');return new Promise((resolve,reject)=>{let timer;const clear=()=>{clearTimeout(timer);this.pending=null;};this.pending={match,resolve:m=>{clear();resolve(m);},reject:e=>{clear();reject(e);}};timer=setTimeout(()=>{this.close();reject(new Error('A pedaleira não respondeu. Reconecte; nenhum comando será repetido automaticamente.'));},timeout);try{this.output.send(data);}catch(e){this.pending.reject(e);}});}
  async identify(){const m=await this.request([240,126,0,6,1,247],m=>m.length>=6&&m[0]===240&&m[1]===126&&m[3]===6&&m[4]===2);const result=identity(m);const s=body(await this.request(frame([1]),m=>m.length>=7&&m[0]===240&&m[1]===82&&m[3]===97&&m[4]===0));assert(s.length===2&&s[0]===0&&s[1]===11,'A pedaleira precisa estar ligada no modo normal, fora do modo firmware.');return result;}
  close(){if(this.closed)return;this.closed=true;this.input.removeEventListener('midimessage',this.receive);if(this.pending)this.pending.reject(new Error('Conexão encerrada.'));this.onDisconnect?.();}
}
